<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Event;

use Override;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\PlatformIdentity;
use Civi\Lughauth\Shared\Event\PublicEvent;

class PlatformIdentityUpdateEvent extends PlatformIdentityEvent implements PublicEvent
{
    public function __construct(
        PlatformIdentity $payload,
        public readonly PlatformIdentity $original
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'platform-identity.update';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return $this->original->asPublicJson();
    }
}
